  (* [comment removed for export] *)
  Lemma pxd_B1 : forall regs m (data : Z),
    (1 <= data)%Z -> (data < 2 ^ 64)%Z ->
    rdn SEGS m (rl dA_1f430 0x1f438) 8 = Some (Z_to_le_bytes 8 (0x15b38 + dF_15b38)) ->
    getr regs 10 = Z_to_bv 64 data ->
    exists regs',
      msteps SEGS (mkst regs (rl dOL_23c24 0x23c5c) m rom) (mkst regs' (rl dF_15b38 0x15b38) m rom)
      /\ getr regs' 10 = Z_to_bv 64 data /\ getr regs' 1 = rl dOL_23c24 0x23c6c
