  Lemma pxd_C0 : forall regs m (s pix : Z) (v : pixv),
    (32 <= s)%Z -> (s < 2 ^ 64)%Z -> PIXat m pix v -> p_text v = 0%Z -> p_cmap v = 0%Z ->
